import("./node_modules/@re-cinq/eslint-plugin-re-lint/dist/rules/lib/spec-link-index.mjs").then(({ readSpecFiles, buildLinkIndex }) => {
  const index = buildLinkIndex(readSpecFiles("."));
  for (const file of ["src/orchestration/chatOrchestrator.test.ts", "src/orchestration/chatOrchestratorUsage.acceptance.test.ts"]) {
    const lines = fs.readFileSync(file, "utf8").split("\n");
    const entry = index.get(file);
    lines.forEach((line, idx) => {
      const match = line.match(/^\s*(?:it|test)\s*\(\s*["\x27`](.*?)["\x27`]/);
      if (match) {
        const lineNum = idx + 1;
        const linked = entry && entry.lines.has(lineNum);
        console.log(`${file}:${lineNum} [${linked ? "LINKED" : "UNLINKED"}] ${match[1]}`);
      }
    });
  }
});
'
